INSERT [Kategorije] ([KategorijaID], [Naziv], [Opis], [Slika]) VALUES (1, N'Sport', N'Razne sportske manifestacije', )
INSERT [Kategorije] ([KategorijaID], [Naziv], [Opis], [Slika]) VALUES (2, N'Konferencije', N'Konferencije su profesionalni događaji koji okupljaju stručnjake, govornike i učesnike s ciljem razmjene znanja, iskustava i ideja iz određenog područja. Održavaju se u formalnom okruženju i obično uključuju predavanja, radionice, panele i mreženje. Idealne su za usavršavanje, praćenje najnovijih trendova i povezivanje sa zajednicom.', )
INSERT [Kategorije] ([KategorijaID], [Naziv], [Opis], [Slika]) VALUES (3, N'Koncerti', N'Koncerti su muzički događaji koji okupljaju izvođače i publiku u zajedničkom doživljaju muzike uživo. Bilo da se radi o velikim arenama, klubovima ili otvorenim prostorima, koncerti nude jedinstvenu atmosferu i energiju izvođenja pred publikom. Idealni su za ljubitelje muzike svih žanrova — od rocka i popa do klasike i elektronske muzike.', )
INSERT [Kategorije] ([KategorijaID], [Naziv], [Opis], [Slika]) VALUES (4, N'Festival', N'Festivali su višednevni događaji koji slave muziku, umjetnost, kulturu, film, hranu ili druge tematske sadržaje. Okupljaju veliki broj ljudi i često nude bogat program koji uključuje nastupe, radionice, izložbe i zabavu na otvorenom. Savršeni su za one koji žele doživjeti jedinstvenu atmosferu, raznolik sadržaj i nezaboravne trenutke.', )
INSERT [Kategorije] ([KategorijaID], [Naziv], [Opis], [Slika]) VALUES (5, N'Sajam', N'Događaji koji okupljaju izlagače i posjetitelje s ciljem predstavljanja i promocije proizvoda, usluga ili ideja iz određene industrije ili tematskog područja. Sajmovi mogu biti otvoreni za širu javnost ili rezervisani za stručnjake iz određene oblasti.', )
INSERT [Kategorije] ([KategorijaID], [Naziv], [Opis], [Slika]) VALUES (6, N'Predstave', N'Scenski događaji koji uključuju izvođenje dramskih, muzičkih, plesnih ili komičnih sadržaja pred publikom. Obuhvata različite oblike umjetničkog izražavanja poput drama, mjuzikala, monodrama i drugih izvedbi, bez obzira na lokaciju održavanja.', )
