INSERT [Dogadjaji] ([DogadjajID], [Naziv], [DatumOd], [DatumDo], [Program], [Naslovna], [Opis], [Website], [Lokacija], [LokacijaSlika], [DobavljacID], [KategorijaID], [Status], [PodkategorijaID], [Organizator], [ProgramSlika], [Created], [Latitude], [Longitude]) VALUES (1, N'ARTES Tech 2025 Sarajevo', CAST(N'2025-09-27T11:00:00.000' AS DateTime), CAST(N'2025-09-27T23:59:00.000' AS DateTime), N'Uskoro.', , N'Udruženje za istraživanje, tehnologiju, edukaciju i nauku – ARTES, uz podršku Federalnog ministarstva obrazovanja i nauke, Univerziteta u Sarajevu, 24tech e-magazina, partnerskih kompanija i donatora, ove godine u Sarajevu organizuje tehnološku konferenciju ARTES TECH 2025 sa medunarodnim ucešcem, s ciljem okupljanja IT strucnjaka iz regiona', N'konferencija.artesbh.org', N'Cinestar 4DX Sarajevo', 0x, 1, 2, N'ACTIVE', 2, N'admin', 0x, CAST(N'2025-07-02T21:03:06.5973528' AS DateTime2), 43.8506541, 18.3549713)
INSERT [Dogadjaji] ([DogadjajID], [Naziv], [DatumOd], [DatumDo], [Program], [Naslovna], [Opis], [Website], [Lokacija], [LokacijaSlika], [DobavljacID], [KategorijaID], [Status], [PodkategorijaID], [Organizator], [ProgramSlika], [Created], [Latitude], [Longitude]) VALUES (2, N'Sarajevo Run', CAST(N'2025-08-09T10:00:00.000' AS DateTime), CAST(N'2025-08-09T12:00:00.000' AS DateTime), N'10:00 - Start of the run', , N'????? Make Friends & Run Together ?????
Every Saturday from 10:00 to 12:00 AM
Looking to get moving and meet new people?
Join us for a friendly group run – open to all levels! No need to be a pro runner – the goal is to run together and make new friends along the way ????
?? We start at 10:00 sharp – try to arrive a little early
??Bring some water and a good vibe!
Registration is very cheap but mandatory to enter our community, get the location and cover our advertisement fees ??. To keep things safe and organized, only those who have registered will be able to join the group.', NULL, N'Vilsonovo setaliste Sarajevo', 0x, 3, 1, N'ACTIVE', NULL, N'user', 0x, CAST(N'2025-07-02T21:31:42.6796301' AS DateTime2), 43.8530338, 18.3929212)
INSERT [Dogadjaji] ([DogadjajID], [Naziv], [DatumOd], [DatumDo], [Program], [Naslovna], [Opis], [Website], [Lokacija], [LokacijaSlika], [DobavljacID], [KategorijaID], [Status], [PodkategorijaID], [Organizator], [ProgramSlika], [Created], [Latitude], [Longitude]) VALUES (3, N'Music Reactions Outdoor Rave Sarajevo', CAST(N'2025-07-26T16:00:00.000' AS DateTime), CAST(N'2025-07-26T23:58:00.000' AS DateTime), N'Lúcia Lu, berlinska DJica i ikona, poznata je po svojoj energicnoj prisutnosti i raznolikom muzickom izboru. Njena nepredvidiva muzicka selekcija govori o širini i svestranosti same umetnice. Širokim spektrom promišljene muzicke selekcije ona može da u dva koraka prede od densa do žestokog rejva. Kada je ona iza dekova, od njenih setova i nje same ne možete ocekivati ništa manje nego apsolutni maksimum – muzicki, kao i fizicki.
Yasmin Gardezi, u kratkom vremenskom periodu je postala jedan od najtraženijih DJ-eva u Irskoj. Yasmin je ostvarila znacajan uspeh i ostaje jedan od najperspektivnijih talenata u zemlji, inspirišuci mnoge koji žele da zapocnu svoju DJ karijeru. Mlada umetnica godinama razvija svoj jedinstveni zvuk koji obuhvata brze, energicne i hipnoticne tehno trake, a može se reci i da se ucvrstila kao znacajno ime na najvecim svetskim festivalima.
Toximami, sa sedištem u Berlinu, Sabrina je egipatsko-nemacka DJ-ica i producentkinja koja se na elektronskoj muzickoj sceni istice jedinstvenim spojem tamnih i melodijskih zvukova. Kombinuje pop-kulturne uticaje sa specificnim elektronskim podžanrovima, stvarajuci muzicki identitet koji ocarava slušaoce širom sveta.
ACOR, producent i DJ iz Novog Sada, Srbija. Krenuo je na svoje muzicko putovanje u 14. godini, sa dubokom strašc´u ka esidu, šrancu i rejv stilovima tehna. Trenutno se istice kao jedan od najperspektivnijih i najuspešnijih tehno umetnika u Srbiji, predodreden za svetsko priznanje. ACOR-ove trake su predstavljene u setovima renomiranih tehno umetnika širom sveta. Njegov zvuk je intenzivan i beskompromisan, ali takode ceni atmosfersku i emotivnu dimenziju rejva.', , N'Music Reactions nastavlja regionalno širenje rejv energije u Bosni i Hercegovini! U saradnji sa ekipom Garden of Dreams, prvi Music Reactions Outdoor Rave u Sarajevu desice se 26. jula i po prvi put to ce biti dnevni rejv! Ovaj spektakl održace se na kultnoj lokaciji Ars Aevi Plato glavnog grada Bosne i Hercegovine. Na ovom lineupu ocekuju vas tri izuzetne dame i tri fantasticna momka, svi sa jedinstvenim stilovima i energijom koja ce vas oduševiti.', N'musicreactions.com', N'Ars Aevi Sarajevo', 0x, 2, 3, N'ACTIVE', 3, N'user', , CAST(N'2025-07-03T17:48:24.1104994' AS DateTime2), 43.8589546, 18.433262199999998)
INSERT [Dogadjaji] ([DogadjajID], [Naziv], [DatumOd], [DatumDo], [Program], [Naslovna], [Opis], [Website], [Lokacija], [LokacijaSlika], [DobavljacID], [KategorijaID], [Status], [PodkategorijaID], [Organizator], [ProgramSlika], [Created], [Latitude], [Longitude]) VALUES (4, N'FK Sarajevo vs FC Universitatea Craiova', CAST(N'2025-07-24T21:00:00.000' AS DateTime), CAST(N'2025-07-24T23:57:00.000' AS DateTime), NULL, , N'Evropska groznica pocinje da trese Koševo! ??
Ulaznice za utakmicu protiv ekipe Universitatea Craiova (Rumunija) bit ce puštene u prodaju od 12:00.
Spremi se za evropsku noc koju ne želiš propustiti!', NULL, N'Asim Ferhatovic Hase Stadium', , 1, 1, N'ACTIVE', NULL, N'user', 0x, CAST(N'2025-07-03T18:02:16.1544356' AS DateTime2), 43.8737169, 18.4086321)
INSERT [Dogadjaji] ([DogadjajID], [Naziv], [DatumOd], [DatumDo], [Program], [Naslovna], [Opis], [Website], [Lokacija], [LokacijaSlika], [DobavljacID], [KategorijaID], [Status], [PodkategorijaID], [Organizator], [ProgramSlika], [Created], [Latitude], [Longitude]) VALUES (5, N'Sarajevo Street Food Market', CAST(N'2025-07-03T12:00:00.000' AS DateTime), CAST(N'2025-07-23T12:00:00.000' AS DateTime), NULL, , N'Ovo ljeto se vraca jedinstveni sarajevski street food festival – u još uzbudljivijem izdanju.
Ponovno ce se širiti mirisi kojima je teško odoljeti – okusi specijaliteta iz svih krajeva svijeta zauzet ce Vilsonovo šetalište i pretvoriti ga u epicentar grada.', N'instagram.com/streetfoodmarket.sa', N'Vrbanja 1 Sarajevo', 0x, NULL, 4, N'ACTIVE', 6, N'user', , CAST(N'2025-07-03T17:38:19.1852580' AS DateTime2), 43.8554008, 18.4081162)
INSERT [Dogadjaji] ([DogadjajID], [Naziv], [DatumOd], [DatumDo], [Program], [Naslovna], [Opis], [Website], [Lokacija], [LokacijaSlika], [DobavljacID], [KategorijaID], [Status], [PodkategorijaID], [Organizator], [ProgramSlika], [Created], [Latitude], [Longitude]) VALUES (6, N'Moba - Street Food Festival Mostar', CAST(N'2025-08-27T12:00:00.000' AS DateTime), CAST(N'2025-09-07T12:00:00.000' AS DateTime), N'Probajte razlicita jela iz 12 gastro kutaka, a 12 dana rezervirajte za druženje, degustaciju, ples i pjevanje jer vas ocekuje 12 koncerata renomiranih izvodaca razlicitih muzickih žanrova. Uživajte uz poznate lokalne i regionalne umjetnike, Moba resident DJ-a, program za djecu, kreativne radionice i još mnoštvo zanimljivog sadržaja.', , N'Okusi svijet na jednom mjestu - Moba Street Food Festival je i ovo ljeto s vama!
Mostarsko ljeto ce se cetvrtu godinu zaredom spojiti s okusima i mirisima street food delicija. Ovaj omiljeni dogadaj okuplja ljubitelje dobrog zalogaja i avanturisticke kulinarske duše kako bi istražili raznolikost svjetskih okusa. Od azijskih, meksickih preko talijanskih do tradicionalnih jela s potpisom lokalnih i regionalnih kuhara, Moba Street Food Festival obecava da ce probuditi nepca svim gastroljupcima, a uz ukusne zalogaje, moci cete se rashladiti raznolikom ponudom osvježavajucih pica i cocktaila.', NULL, N'Spanjolski trg 1, Mostar', 0x, NULL, 4, N'ACTIVE', 6, N'user', , CAST(N'2025-07-03T17:40:05.3040219' AS DateTime2), 43.3431517, 17.8073667)
INSERT [Dogadjaji] ([DogadjajID], [Naziv], [DatumOd], [DatumDo], [Program], [Naslovna], [Opis], [Website], [Lokacija], [LokacijaSlika], [DobavljacID], [KategorijaID], [Status], [PodkategorijaID], [Organizator], [ProgramSlika], [Created], [Latitude], [Longitude]) VALUES (7, N'Live Stage Sarajevo', CAST(N'2025-07-03T22:00:00.000' AS DateTime), CAST(N'2025-07-05T12:00:00.000' AS DateTime), N'Cetvrtak 03.07.
ZOSTER
S.A.R.S.
SKROZ
DEMINUTIV

Petak 04.07.
BOMBAJ ŠTAMPA
PSIHOMODO POP
MILE KEKIN
ZRACNA KONTROLA

Subota 05.07.
METALLICA REAL TRIBUTE SYMPHONY
DIVLJE JAGODE
FLASTER', , N'Predstavljamo Vam 6. izdanje Live Stage Festivala koje ce se održati od 03.7. do 05.7. 2025. godine u srcu Sarajeva, na sportskom igralištu ''''Metalac''''. Kao veliko osvježenje, na ovogodišnje izdanje festivala dolazi nam METALLICA REAL TRIBUTE SYMPHONY, jedini licencirani tribute Metallica bend koji ce nastupiti u pratnji simfonijskog orkestra koji cini cak 45 vrhunskih muzicara. Pored njih, ovogodišnji line up festivala cine Zoster, Divlje Jagode, S.A.R.S., Bombaj Štampa, Psihomodo Pop, Mile Kekin, Skroz, Deminutiv, Zracna Kontola i Flaster.', NULL, N'Metalac Sarajevo', 0x, 1, 4, N'ACTIVE', 7, N'janedoe', 0x, CAST(N'2025-07-03T19:03:20.7937619' AS DateTime2), 43.856258600000004, 18.4130763)
INSERT [Dogadjaji] ([DogadjajID], [Naziv], [DatumOd], [DatumDo], [Program], [Naslovna], [Opis], [Website], [Lokacija], [LokacijaSlika], [DobavljacID], [KategorijaID], [Status], [PodkategorijaID], [Organizator], [ProgramSlika], [Created], [Latitude], [Longitude]) VALUES (8, N'Sajam beautiFUL 2025', CAST(N'2025-09-06T12:00:00.000' AS DateTime), CAST(N'2025-09-07T21:00:00.000' AS DateTime), N'Izlagaci:
-Olival
-Afrodita
